// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }

    function testFuzz_property(uint256 newMinSum) public {
        // Freeze configuration: initialization closes SetMinSum/SetLogFile forever.
        c.Initialized();

        // A post-initialization SetMinSum must ALWAYS revert, for any value.
        bool ok;
        try c.SetMinSum(newMinSum) { ok = true; } catch { ok = false; }

        assertTrue(ok == false && c.MinSum() == 0);
    }
}
